WFJ.Data.add("spell", {
  [403195] = { "Mentre sei in ⟦Defensive Stance=Postura da Difesa⟧ e hai uno scudo equipaggiato, ⟦Sunder Armor=Incrinatura⟧ infligge anche danni pari al $N1% dei danni al secondo dell'arma equipaggiata, aumentati del $N2% per ogni applicazione di ⟦Sunder Armor=Incrinatura⟧ già presente sul bersaglio. I danni di Sfondamento generano un'elevata quantità di minaccia mentre sei in ⟦Defensive Stance=Postura da Difesa⟧.", nil, 0x4680b9c4, nil, "um" },
  [403196] = { "⟦Sunder Armor=Incrinatura⟧ infligge anche il $N1% dei danni dell'arma, aumentati del $N2% per ogni applicazione di ⟦Sunder Armor=Incrinatura⟧ già presente sul bersaglio.", nil, 0xe179bc13, nil, "um" },
  [403215] = { "Il Guerriero lancia un grido che aumenta di $N2 la Tempra di tutti i membri del gruppo entro $N1 m. Dura $D1.", "Aumenta la tua Tempra di $N1.", 0x29b58dd9, 0xe48c31d9, "uu" },
  [403218] = { "Generi il $N1% di rabbia in più da tutti i danni che infliggi.", nil, 0x81796ad9, nil, "um" },
  [403219] = { "⟦Thunder Clap=Schianto del Tuono⟧ ora aumenta l'intervallo tra gli attacchi di un ulteriore $N1%, può essere usato in qualsiasi postura, infligge il $N2% di danni in più e genera il $N3% di minaccia in più.", nil, 0x4be71a9f, nil, "um" },
  [403228] = { "Lancia una catena uncinata per immobilizzare il bersaglio e trascinarlo verso di te. Non può essere usata su nemici di livello superiore a $N1 o contrassegnati come boss.", nil, 0x59834f59, nil, "um" },
  [403231] = { "Lancia una catena uncinata per immobilizzare il bersaglio e trascinarlo verso di te.", nil, 0x752fe057, nil, "um" },
  [403233] = { "Lancia una catena uncinata per immobilizzare il bersaglio e trascinarlo verso di te. I bersagli non possono essere storditi mentre vengono trascinati.", "Immune agli effetti di stordimento.", 0x5b438027, 0xfd2ef3a2, "uu" },
  [403332] = { "Spara al bersaglio infliggendo il $N1% dei danni dell'arma a distanza. Genera $N2 rabbia.", "Silenziato.", 0x1499b476, 0x20816e34, "uu" },
  [403344] = { "Ottieni l'abilità Flagellazione:\n\n$I1\nOttieni rabbia dai danni fisici subiti come se non indossassi alcuna armatura.", nil, 0xbe362153, nil, "um" },
  [403349] = { "Ottieni l'abilità Rabbia Infinita:\n\n$I1\nGeneri il $N1% di rabbia in più da tutti i danni che infliggi.", nil, 0xe0747ccf, nil, "um" },
  [403352] = { "Ottieni l'abilità Frenesia del Sangue:\n\n$I1\nSquartamento ora può essere usato in Postura da Berserker, i danni di Squartamento aumentano del $N1% e Squartamento infligge danni aggiuntivi pari al $N2% della tua potenza d'attacco ogni volta che infligge danni.", nil, 0xf85bd772, nil, "um" },
  [403355] = { "Ottieni l'abilità Sfondamento:\n\n$I1\nMentre sei in Postura da Difesa e hai uno scudo equipaggiato, Incrinatura infligge anche danni pari al $N1% dei danni al secondo dell'arma equipaggiata, aumentati del $N2% per ogni applicazione di Incrinatura già presente sul bersaglio. I danni di Sfondamento generano un'elevata quantità di minaccia mentre sei in Postura da Difesa.", nil, 0xd58c3803, nil, "um" },
  [403356] = { "Ottieni l'abilità Furious Thunder:\n\n$I1\nSchianto del Tuono ora aumenta l'intervallo tra gli attacchi di un ulteriore $N1%, può essere usato in qualsiasi postura, infligge il $N2% di danni in più e genera il $N3% di minaccia in più.", nil, 0x92a5c382, nil, "um" },
  [403359] = { "Ottieni l'abilità Rigenerazione Furente:\n\n$I1\nTi cura del $N1% della tua salute massima in $D1, ma è utilizzabile solo mentre è attivo Rabbia, Furia del Berserker o Rabbia del Sangue. Utilizzabile anche durante gli stordimenti.", nil, 0xf25738b5, nil, "um" },
  [403434] = { "Ottieni l'abilità Frenesia di Vittoria:\n\n$I1\nAttacca istantaneamente il bersaglio, infliggendo $N1 danni e curandoti del $N2% della tua salute massima. Utilizzabile solo entro $D1 dall'uccisione di un nemico non banale.", nil, 0x5fa024af, nil, "um" },
  [403435] = { "Ottieni l'abilità Urlo di Comando:\n\n$I1\nIl Guerriero lancia un urlo che aumenta di $N2 la Tempra di tutti i membri del gruppo entro $N1 m. Dura $D1.", nil, 0x0ff18add, nil, "um" },
  [403436] = { "Ottieni l'abilità Meathook:\n\n$I1\nLancia una catena uncinata per immobilizzare il bersaglio e trascinarlo verso di te. Non può essere usata su nemici di livello superiore a $N1 o contrassegnati come boss.", nil, 0x6b8c91ca, nil, "um" },
  [403446] = { "Incidi sui tuoi gambali la runa Urlo di Comando:\n\n$I1\nIl Guerriero lancia un urlo che aumenta di $N2 la Tempra di tutti i membri del gruppo entro $N1 m. Dura $D1.", nil, 0x3c6f1263, nil, "um" },
  [403467] = { "Incidi sui tuoi stivali la runa Rigenerazione Furente:\n\n$I1\nTi cura del $N1% della tua salute massima in $D1, ma è utilizzabile solo mentre è attivo Rabbia, Furia del Berserker o Rabbia del Sangue. Utilizzabile anche durante gli stordimenti.", nil, 0xb2c4471e, nil, "um" },
  [403470] = { "Incidi sui tuoi guanti la runa Frenesia di Vittoria:\n\n$I1\nAttacca istantaneamente il bersaglio, infliggendo $N1 danni e curandoti del $N2% della tua salute massima. Utilizzabile solo entro $D1 dall'uccisione di un nemico non banale.", nil, 0x42598b5d, nil, "um" },
  [403474] = { "Incidi sulla tua armatura per il torso la runa Frenesia del Sangue:\n\n$I1\nSquartamento ora può essere usato in Postura da Berserker, i danni di Squartamento aumentano del $N1% e Squartamento infligge danni aggiuntivi pari al $N2% della tua potenza d'attacco ogni volta che infligge danni.", nil, 0x248e9934, nil, "um" },
  [403475] = { "Incidi sui tuoi guanti la runa Sfondamento:\n\n$I1\nMentre sei in Postura da Difesa e hai uno scudo equipaggiato, Incrinatura infligge anche danni pari al $N1% dei danni al secondo dell'arma equipaggiata, aumentati del $N2% per ogni applicazione di Incrinatura già presente sul bersaglio. I danni di Sfondamento generano un'elevata quantità di minaccia mentre sei in Postura da Difesa.", nil, 0xab06e129, nil, "um" },
  [403476] = { "Incidi sui tuoi gambali la runa Furious Thunder:\n\n$I1\nSchianto del Tuono ora aumenta l'intervallo tra gli attacchi di un ulteriore $N1%, può essere usato in qualsiasi postura, infligge il $N2% di danni in più e genera il $N3% di minaccia in più.", nil, 0xa31fd64d, nil, "um" },
  [403480] = { "Incidi sulla tua armatura per il torso la runa Flagellazione:\n\n$I1\nOttieni rabbia dai danni fisici subiti come se non indossassi alcuna armatura.", nil, 0x2d2141d2, nil, "um" },
  [403489] = { "Incidi sul tuo elmo la runa Rabbia Infinita:\n\n$I1\nGeneri il $N1% di rabbia in più da tutti i danni che infliggi.", nil, 0xf9c56804, nil, "um" },
  [403501] = { "Invia un'anima spettrale ad assalire il tuo bersaglio attuale, infliggendo $N1 danni e aumentando del $N2% tutti i danni da ombra periodici che infliggi a quel bersaglio per $D1. Quando Tormento termina per qualsiasi motivo, vieni curato del $N4% dei danni che ha inflitto al bersaglio.", "Danni subiti dagli effetti periodici di danni da ombra dell'incantatore aumentati del $N1%.", 0x203fa01a, 0xe0d6f2ae, "uu" },
  [403511] = { "Aumenta del $N1% la salute risucchiata o i danni inflitti da ⟦Drain Life=Risucchio di Vita⟧, Risucchio d'Anima e Distruzione.", nil, 0x2d5a7a50, nil, "um" },
  [403619] = { "Circonda l'incantatore di energia vile, aumentando i danni magici e le cure di $N1, più danni magici e cure aggiuntivi pari al $N2% del tuo Spirito. Inoltre rigeneri il $N3% della tua salute massima ogni $D1. Sullo Stregone può essere attivo un solo tipo di incantesimo Armatura alla volta. Dura $D2.", "Aumenta i danni magici e le cure di $N1. Rigenera inoltre il $N2% della salute massima ogni $D1.", 0x5b3e8f7c, 0xd6ad9fb3, "uu" },
  [403628] = { "Il tuo ⟦Shadow Bolt=Dardo d'Ombra⟧ ora colpisce fino a $N1 bersagli entro una distanza a catena di $N2 m, ma infligge il $N3% di danni in meno.", nil, 0x863def08, nil, "um" },
  [403629] = { "Scaglia contro il nemico un dardo di fuoco caotico che infligge $N1 danni da caos. Dardo del Caos colpisce sempre, non può essere resistito e la sua conoscenza fa sì che tutti i tuoi incantesimi del fuoco superino gli effetti di assorbimento. Dardo del Caos ha un'alta probabilità di essere resistito se usato contro mostri di $N2 o più livelli superiori al tuo.", nil, 0x399a9457, nil, "um" },
  [403650] = { "⟦Rain of Fire=Pioggia di Fuoco⟧ lascia anche al suolo un Lago di Fuoco che aumenta del $N1% tutti i danni da fuoco che tu e il tuo demone infliggete ai nemici colpiti.", "Danni da fuoco subiti aumentati del $N1%.", 0x88d91dc3, 0x729d44b2, "uu" },
  [403666] = { "⟦Rain of Fire=Pioggia di Fuoco⟧ non è più incanalata, ma ottiene un tempo di recupero di $D1.", nil, 0x463d92eb, nil, "um" },
  [403668] = { "⟦Drain Life=Risucchio di Vita⟧ non è più incanalato, dura $D1 con un tempo di recupero di $D2, costa il $N3% di mana in più e ti cura del $N4% in più ogni volta che infligge danni.", nil, 0x2f87e1f1, nil, "um" },
  [403677] = { "Trasferisce $N1 salute ogni secondo dal bersaglio all'incantatore. Dura $D1.", "$N1 salute prosciugata all'incantatore ogni secondo.", 0x55392778, 0x73cfd31b, "uu" },
  [403685] = { "Trasferisce $N1 salute ogni secondo dal bersaglio all'incantatore. Dura $D1.", "$N1 salute prosciugata all'incantatore ogni secondo.", 0x55392778, 0x73cfd31b, "uu" },
  [403686] = { "Trasferisce $N1 salute ogni secondo dal bersaglio all'incantatore. Dura $D1.", "$N1 salute prosciugata all'incantatore ogni secondo.", 0x55392778, 0x73cfd31b, "uu" },
  [403687] = { "Trasferisce $N1 salute ogni secondo dal bersaglio all'incantatore. Dura $D1.", "$N1 salute prosciugata all'incantatore ogni secondo.", 0x55392778, 0x73cfd31b, "uu" },
  [403688] = { "Trasferisce $N1 salute ogni secondo dal bersaglio all'incantatore. Dura $D1.", "$N1 salute prosciugata all'incantatore ogni secondo.", 0x55392778, 0x73cfd31b, "uu" },
  [403689] = { "Trasferisce $N1 salute ogni secondo dal bersaglio all'incantatore. Dura $D1.", "$N1 salute prosciugata all'incantatore ogni secondo.", 0x55392778, 0x73cfd31b, "uu" },
  [403789] = { "Ti trasformi in un demone, aumentando l'Armatura del $N1% e la salute del $N2%, riducendo del $N3% la probabilità di subire colpi critici, aumentando del $N4% la minaccia generata e del $N5% il mana ottenuto da ⟦Life Tap=Conversione Vitale⟧, ma riducendo del $N6% tutti i danni che infliggi. Metamorfosi trasforma il funzionamento di alcune abilità e ne conferisce di nuove:\n\nDolore Ustionante: ora istantaneo.\n\n⟦Shadow Bolt=Dardo d'Ombra⟧: diventa Fendente d'Ombra, un attacco in mischia d'ombra che colpisce fino a $N7 nemici vicini, ma ha un tempo di recupero di $D1.\n\nPaura: sostituita da Menace.\n\n$I1\nProvoca il bersaglio, inducendolo ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.\n\nDemon Charge\n\n$I2\nCarica un nemico e lo stordisce per $D2. Non utilizzabile in combattimento.\n\nDemonic Howl\n\n$I3\nCostringe tutti i nemici vicini a concentrare gli attacchi su di te per $D3.", "Armatura aumentata del $N1%, salute aumentata del $N2%, probabilità di subire colpi critici ridotta del $N3%, minaccia aumentata del $N4%, mana ottenuto da ⟦Life Tap=Conversione Vitale⟧ aumentato del $N5%, danni inflitti ridotti del $N6%, alcune abilità modificate e alcune nuove abilità conferite.", 0x0c431bda, 0x184055a6, "uu" },
  [403816] = { "Ti trasformi in un demone, aumentando l'Armatura del $N1%, riducendo del $N2% la probabilità di subire colpi critici, aumentando del $N3% la minaccia generata e del $N4% il mana ottenuto da ⟦Life Tap=Conversione Vitale⟧, e trasformando il funzionamento di alcune tue abilità:\n\nDolore Ustionante: ora istantaneo.\n\n⟦Shadow Bolt=Dardo d'Ombra⟧: diventa Fendente d'Ombra, un attacco in mischia d'ombra che colpisce fino a $N5 nemici vicini.\n\n⟦Curse of Recklessness=Maledizione dell'Avventatezza⟧: ora provoca anche il bersaglio, inducendolo ad attaccarti per $D1.\n\n⟦Howl of Terror=Grido Terrorizzante⟧: ora costringe anche tutti i nemici vicini ad attaccarti per $D2, ma il suo tempo di recupero sale a $N8 min.", "Armatura aumentata del $N1%, probabilità di subire colpi critici ridotta del $N2%, minaccia aumentata del $N3%, mana ottenuto da ⟦Life Tap=Conversione Vitale⟧ aumentato del $N4% e alcune abilità modificate.", 0xde0d7500, 0x1a04cd8c, "uu" },
  [403828] = { "Costringe il bersaglio ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.", "Provocato.", 0x71de38fd, 0x36f56123, "uu" },
  [403835] = { { "Punisce fino a $N1 nemici vicini con una sferzata d'ombra, infliggendo $N2 danni a ciascuno.\n\nFendente d'Ombra beneficia della maggior parte dei talenti e degli effetti di cui beneficia ⟦Shadow Bolt=Dardo d'Ombra⟧ e li attiva allo stesso modo.\n\nColpire un bersaglio con Fendente d'Ombra ti conferisce anche $N3 danni magici per ogni punto della tua abilità in Difesa oltre $N4. Dura $D1.", "Punisce fino a $N1 nemici vicini con una sferzata d'ombra, infliggendo $N2 danni a ciascuno.\n\nFendente d'Ombra beneficia della maggior parte dei talenti e degli effetti di cui beneficia ⟦Shadow Bolt=Dardo d'Ombra⟧ e li attiva allo stesso modo.", shape = { "5/1", "2/0" } }, nil, 0x436ebc47, nil, "um" },
