  [403852] = { { "Punisce fino a $N1 nemici vicini con una sferzata d'ombra, infliggendo $N2 danni a ciascuno.\n\nFendente d'Ombra beneficia della maggior parte dei talenti e degli effetti di cui beneficia ⟦Shadow Bolt=Dardo d'Ombra⟧ e li attiva allo stesso modo.\n\nColpire un bersaglio con Fendente d'Ombra ti conferisce anche $N3 danni magici per ogni punto della tua abilità in Difesa oltre $N4. Dura $D1.", "Punisce fino a $N1 nemici vicini con una sferzata d'ombra, infliggendo $N2 danni a ciascuno.\n\nFendente d'Ombra beneficia della maggior parte dei talenti e degli effetti di cui beneficia ⟦Shadow Bolt=Dardo d'Ombra⟧ e li attiva allo stesso modo.", shape = { "5/1", "2/0" } }, nil, 0x436ebc47, nil, "um" },
  [403858] = { "Ottieni l'abilità Tormento:\n\n$I1\nInvia un'anima spettrale ad assalire il tuo bersaglio attuale, infliggendo $N1 danni e aumentando del $N2% tutti i danni da ombra periodici che infliggi a quel bersaglio per $D1. Quando Tormento termina per qualsiasi motivo, vieni curato del $N4% dei danni che ha inflitto al bersaglio.", nil, 0xefc123b0, nil, "um" },
  [403860] = { "Ottieni l'abilità Dardo del Caos:\n\n$I1\nScaglia contro il nemico un dardo di fuoco caotico che infligge $N1 danni da caos. Dardo del Caos colpisce sempre, non può essere resistito e la sua conoscenza fa sì che tutti i tuoi incantesimi del fuoco superino gli effetti di assorbimento. Dardo del Caos ha un'alta probabilità di essere resistito se usato contro mostri di $N2 o più livelli superiori al tuo.", nil, 0xb167a637, nil, "um" },
  [403863] = { "Ottieni l'abilità ⟦Soul Siphon=Aspirazione dell'Anima⟧:\n\n$I1\nAumenta del $N1% la salute risucchiata o i danni inflitti da Risucchio di Vita, Risucchio d'Anima e Distruzione.", nil, 0xf0a55192, nil, "um" },
  [403868] = { "Ottieni l'abilità Master Channeler:\n\n$I1\nRisucchio di Vita non è più incanalato, dura $D1 con un tempo di recupero di $D2, costa il $N3% di mana in più e ti cura del $N4% in più ogni volta che infligge danni.", nil, 0x0fa6b05e, nil, "um" },
  [403871] = { "Ottieni l'abilità ⟦Shadow Bolt Volley=Raffica di Dardi d'Ombra⟧:\n\n$I1\nIl tuo Dardo d'Ombra ora colpisce fino a $N1 bersagli entro una distanza a catena di $N2 m, ma infligge il $N3% di danni in meno.", nil, 0x4bf5368a, nil, "um" },
  [403872] = { "Ottieni l'abilità Lago di Fuoco:\n\n$I1\nPioggia di Fuoco non è più incanalata, ma ottiene un tempo di recupero di $D1.", nil, 0x14156e4c, nil, "um" },
  [403873] = { "Ottieni l'abilità Metamorfosi:\n\n$I1\nTi trasformi in un demone, aumentando l'Armatura del $N1% e la salute del $N2%, riducendo del $N3% la probabilità di subire colpi critici, aumentando del $N4% la minaccia generata e del $N5% il mana ottenuto da Conversione Vitale, ma riducendo del $N6% tutti i danni che infliggi. Metamorfosi trasforma il funzionamento di alcune abilità e ne conferisce di nuove:\n\nDolore Ustionante: ora istantaneo.\n\nDardo d'Ombra: diventa Fendente d'Ombra, un attacco in mischia d'ombra che colpisce fino a $N7 nemici vicini, ma ha un tempo di recupero di $D1.\n\nPaura: sostituita da Menace.\n\n$I2\nProvoca il bersaglio, inducendolo ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.\n\nDemon Charge\n\n$I3\nCarica un nemico e lo stordisce per $D2. Non utilizzabile in combattimento.\n\nDemonic Howl\n\n$I4\nCostringe tutti i nemici vicini a concentrare gli attacchi su di te per $D3.", nil, 0xfeedaba7, nil, "um" },
  [403919] = { "Incidi sui tuoi guanti la runa Tormento:\n\n$I1\nInvia un'anima spettrale ad assalire il tuo bersaglio attuale, infliggendo $N1 danni e aumentando del $N2% tutti i danni da ombra periodici che infliggi a quel bersaglio per $D1. Quando Tormento termina, per qualsiasi motivo, ricevi una cura pari al $N4% dei danni che ha inflitto al bersaglio.", nil, 0xb53071bc, nil, "um" },
  [403920] = { "Incidi sul tuo mantello la runa ⟦Soul Siphon=Aspirazione dell'Anima⟧:\n\n$I1\nAumenta del $N1% la salute prosciugata o i danni inflitti dai tuoi incantesimi Risucchio di Vita, Risucchio d'Anima e Distruzione.", nil, 0x85fe4825, nil, "um" },
  [403925] = { "Incidi sui tuoi guanti la runa Dardo del Caos:\n\n$I1\nScaglia un dardo di fuoco caotico contro il nemico, infliggendo $N1 danni da caos. Dardo del Caos colpisce sempre, non può essere resistito e la sua conoscenza fa sì che tutti i tuoi incantesimi di fuoco superino gli effetti di assorbimento. Dardo del Caos ha un'alta probabilità di essere resistito se usato contro mostri di $N2 o più livelli superiori al tuo.", nil, 0x5c5b5d0f, nil, "um" },
  [403932] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Master Channeler:\n\n$I1\nIl tuo Risucchio di Vita non è più canalizzato, dura $D1 con un tempo di recupero di $D2, costa il $N3% di mana in più e ti cura il $N4% in più ogni volta che infligge danni.", nil, 0x6b79271a, nil, "um" },
  [403936] = { "Incidi sui tuoi guanti la runa ⟦Shadow Bolt Volley=Raffica di Dardi d'Ombra⟧:\n\n$I1\nIl tuo Dardo d'Ombra ora colpisce fino a $N1 bersagli entro una distanza di concatenazione di $N2 m, ma con danni ridotti del $N3%.", nil, 0xd7274e80, nil, "um" },
  [403937] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Lago di Fuoco:\n\n$I1\nLa tua Pioggia di Fuoco non è più canalizzata, ma ha un tempo di recupero di $D1.", nil, 0xad16c7f5, nil, "um" },
  [403938] = { "Incidi sui tuoi guanti la runa Metamorfosi:\n\n$I1\nTi trasformi in un demone, aumentando l'Armatura del $N1% e la salute del $N2%, riducendo del $N3% la probabilità di subire colpi critici, aumentando la tua minaccia del $N4% e il mana ottenuto da Conversione Vitale del $N5%, ma riducendo del $N6% tutti i danni che infliggi. Metamorfosi trasforma il funzionamento di alcune abilità e ne conferisce di nuove:\n\nDolore Ustionante: ora istantaneo.\n\nDardo d'Ombra: diventa Fendente d'Ombra, un attacco in mischia da ombra che colpisce fino a $N7 nemici vicini, ma ha un tempo di recupero di $D1.\n\nPaura: sostituita da Menace.\n\n$I2\nProvoca il bersaglio, inducendolo ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.\n\nDemon Charge\n\n$I3\nCarica un nemico e lo stordisce per $D2. Non utilizzabile in combattimento.\n\nDemonic Howl\n\n$I4\nCostringe tutti i nemici vicini a concentrare gli attacchi su di te per $D3.", nil, 0x81ea995a, nil, "um" },
})
